// My earlier tracker data came from a Drive export that TRUNCATED at row 117 of ~226.
// Reading the tab through the Sheets API instead returns every row.
function s(v) { return String(v == null ? '' : v).trim(); }
function norm(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }

const trk = $('Read Deal Tracker').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + pipe.length + ' rows'); }

// locate the investor-name and deal-list columns by header text
const cols = Object.keys(trk[0] || {});
let cInv = null; const cDeals = [];
for (const c of cols) {
  const l = c.toLowerCase();
  if (!cInv && (l.indexOf('investor') >= 0 || l.indexOf('vc name') >= 0)) { cInv = c; }
  if (l.indexOf('deals shared') >= 0 || l.indexOf('latest deal') >= 0 || l.indexOf('picked') >= 0) { cDeals.push(c); }
}
if (!cInv || cDeals.length === 0) { throw new Error('ABORT: could not find tracker columns. Headers: ' + cols.join(' | ')); }

// investor -> set of normalised startup names already shared
const shared = {};
let trkRows = 0;
for (const r of trk) {
  const inv = s(r[cInv]);
  if (!inv) { continue; }
  trkRows++;
  const k = norm(inv);
  if (!shared[k]) { shared[k] = { name: inv, deals: {} }; }
  for (const c of cDeals) {
    for (const d of s(r[c]).split(/[,;\n]/)) {
      const t = norm(d);
      if (t.length > 2) { shared[k].deals[t] = s(d); }
    }
  }
}

// every PENDING pipeline row whose pair appears in the tracker
const conflicts = [];
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() === 'yes') { continue; }
  if (s(p.pause) !== '') { continue; }
  const ik = norm(p.investor);
  const rec = shared[ik];
  if (!rec) { continue; }
  const sk = norm(p.startup);
  let hit = rec.deals[sk];
  if (!hit) {
    for (const d of Object.keys(rec.deals)) {
      if (d.length > 3 && sk.length > 3 && (d.indexOf(sk) >= 0 || sk.indexOf(d) >= 0)) { hit = rec.deals[d]; break; }
    }
  }
  if (hit) {
    conflicts.push({ deal_id: s(p.deal_id), investor: s(p.investor), startup: s(p.startup),
                     next_due: s(p.next_due), notes: s(p.notes).slice(0, 60), tracker_says: hit });
  }
}

const byInv = {};
for (const c of conflicts) { byInv[c.investor] = (byInv[c.investor] || 0) + 1; }
return [{ json: {
  tracker_rows_read: trkRows,
  tracker_investors: Object.keys(shared).length,
  pipeline_rows: pipe.length,
  PENDING_CONFLICTS: conflicts.length,
  by_investor: byInv,
  conflicts: conflicts.slice(0, 120)
}}];
